    public static class ArthurSchnitzler
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Das Wichtigste im Verkehr mit Menschen: ihnen ihre Ausrede wegräumen.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Ich liebe mein Vaterland nicht, weil es mein Vaterland ist, sondern weil ich es schön finde. Ich habe Heimatgefühl, aber keinen Patriotismus.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Weiche hundert Schritte ab vom gebahnten Pfad, und du findest dich allein. Und wenn du einem begegnest, weißt du nicht, ob er die Einsamkeit sucht wie du oder auf Raub ausgeht.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Wer einmal völlig begriffen hat, dass er sterblich ist, für den hat eigentlich die Agonie schon begonnen.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Wer Materie sagt, sagt Geist, ob er es will oder nicht. Denn sie wäre überhaupt nicht vorstellbar ohne Geist. Und wer Geist sagt, sagt Materie, denn ohne Materie könnte er es nicht sagen, nicht einmal denken.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Wie eilig ordnet sich Geschehnes ein.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Ein Abschied schmerzt immer, auch wenn man sich schon lange darauf freut.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Aus dem Werke manches Dichters spüren wir wohl heraus, dass er irgendwie und irgendwo ein Genie ist, nur leider gerade nicht in seiner Dichtung.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Bereit sein ist viel, warten können ist mehr, doch erst den rechten Augenblick nützen ist alles.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Die Eigenschaften unserer Nebenmenschen sind uns immer nur ihrer qualitativen Bedeutung nach offenbar; und es ist nie vorzusehen, bis zu welchem Grad irgendeine Eigenschaft unter bestimmten Umständen sich zu entwickeln vermag.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "In den Beziehungen zwischen Menschen gibt es so wenig einen Stillstand wie im Leben des Einzelnen.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Jeder Dichter ist Realist und Idealist, Impressionist und Expressionist, Naturalist und Symbolist zugleich, oder er ist überhaupt keiner.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Wie sinnlos die Welt dir erscheinen mag, vergiss nie, dass du durch dein Handeln wie durch dein Unterlassen dein redlich Teil zu dieser Sinnlosigkeit beiträgst.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Der Dichter scheint sich vom Literaten manchmal nur durch seine geringere Geschicklichkeit in den Bemühungen um einen äußeren Erfolg zu unterscheiden, der ihm oft erst die Voraussetzung für die Möglichkeit weiteren Schaffens bieten würde oder bietet.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Kein Literat, auch von den glänzendsten Gaben, ist jemals zum Dichter geworden.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Der Enthusiast fühlt sich seiner Sache niemals ganz sicher, daher sein unstillbarer, lästiger Drang, Gefährten seiner Begeisterung zu werben. Der Skeptiker hingegen bedarf stets einer gewissen Isoliertheit, denn schon der Umstand, dass er einen Gefährten seines Zweifels findet, vermag ihn an diesem irre zu machen.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Aufgabe der Erziehung wäre es, den metaphysischen Hunger des Menschen durch Mitteilung von Tatsachen in weisem Maß zu stillen, statt ihn durch Märchen, was ja die Dogmen sind, zu betrügen.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Die Probleme der Sittlichkeit liegen auf dem Gebiet der Verantwortung, die der Sitte auf dem der Tradition.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Ein ernster Mensch sein und keinen Humor haben, das ist zweierlei.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Es fließen ineinander Traum und Wachen, Wahrheit und Lüge. Sicherheit ist nirgends. Wir wissen nichts von anderen, nichts von uns. Wir spielen immer, wer es weiß, ist klug.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Heilige hat es immer gegeben, niemals aber noch einen Menschen, der das Recht gehabt hätte, einen andern Menschen heilig zu sprechen.", Author = "Arthur Schnitzler" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schnitzler", Text = "Horch auf die Verleumder, so wirst du die Wahrheit über dich erfahren.", Author = "Arthur Schnitzler" },
        };
